//! Property tests for a device that syncs to several remotes at once (FIG-196, extends `converge.rs`).
//!
//! Every device mirrors its local folder to each remote on its own: the same `mirror` as with one remote, run
//! once per remote, each with its own "has synced" flag. One remote is healthy and one is flaky. Whatever the
//! order of writes and syncs and however often the flaky one drops, a failure on one remote never stops the
//! other, nothing local is lost, and once the flaky one recovers every device and both remotes hold the same.
//! Everything is generated bytes; nothing here is a real secret.

use std::collections::BTreeMap;
use std::sync::atomic::{AtomicUsize, Ordering};

use figlock_store::{BlobStore, Entry, LocalFolder, StoreError};
use figlock_sync::{Opts, Report, SyncError, mirror};
use proptest::prelude::*;
use tempfile::TempDir;

const VAULT: &str = "vault-1";
const IDS: [&str; 3] = ["aa", "bb", "cc"];

type Files = BTreeMap<String, Vec<u8>>;

fn files(s: &dyn BlobStore) -> Files {
    s.list("")
        .unwrap()
        .into_iter()
        .map(|e| (e.path.clone(), s.get(&e.path).unwrap()))
        .collect()
}

fn vault_json(revision: u64, nonce: u32) -> Vec<u8> {
    serde_json::json!({ "vault_id": VAULT, "revision": revision, "nonce": nonce })
        .to_string()
        .into_bytes()
}

fn revision(s: &dyn BlobStore) -> Option<u64> {
    let v: serde_json::Value = serde_json::from_slice(&s.get("vault.json").ok()?).ok()?;
    v["revision"].as_u64()
}

/// Works for `budget` calls, then fails like a dropped connection.
struct Faulty<'a> {
    inner: &'a LocalFolder,
    budget: AtomicUsize,
}

impl Faulty<'_> {
    fn spend(&self) -> Result<(), StoreError> {
        self.budget
            .try_update(Ordering::SeqCst, Ordering::SeqCst, |n| n.checked_sub(1))
            .map(|_| ())
            .map_err(|_| StoreError::Unavailable)
    }
}

impl BlobStore for Faulty<'_> {
    fn get(&self, p: &str) -> Result<Vec<u8>, StoreError> {
        self.spend()?;
        self.inner.get(p)
    }
    fn put_new(&self, p: &str, b: &[u8]) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.put_new(p, b)
    }
    fn put_replace(&self, p: &str, b: &[u8]) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.put_replace(p, b)
    }
    fn list(&self, p: &str) -> Result<Vec<Entry>, StoreError> {
        self.spend()?;
        self.inner.list(p)
    }
    fn delete(&self, p: &str) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.delete(p)
    }
}

struct Device {
    id: &'static str,
    local: LocalFolder,
    _dir: TempDir,
    /// Per remote: a sync to it has finished here (as `SyncState::synced_before`).
    synced: [bool; 2],
    ops: u32,
}

struct World {
    devices: Vec<Device>,
    remotes: [LocalFolder; 2],
    _dirs: [TempDir; 2],
    unique: u32,
}

fn folder() -> (TempDir, LocalFolder) {
    let d = tempfile::tempdir().unwrap();
    let s = LocalFolder::open(d.path()).unwrap();
    (d, s)
}

impl World {
    fn new(n: usize) -> World {
        let ((d0, r0), (d1, r1)) = (folder(), folder());
        let devices = IDS[..n]
            .iter()
            .map(|id| {
                let (_dir, local) = folder();
                Device {
                    id,
                    local,
                    _dir,
                    synced: [false; 2],
                    ops: 0,
                }
            })
            .collect();
        let w = World {
            devices,
            remotes: [r0, r1],
            _dirs: [d0, d1],
            unique: 0,
        };
        let first = &w.devices[0];
        first
            .local
            .put_replace("vault.json", &vault_json(1, 0))
            .unwrap();
        first
            .local
            .put_replace("devices/aa.json", b"rec-aa")
            .unwrap();
        w
    }

    /// One mirror between device `d` and remote `r`, as `sync::run_remote` does it.
    fn sync_one(&mut self, d: usize, r: usize, budget: Option<usize>) -> Result<Report, SyncError> {
        let dev = &mut self.devices[d];
        let opts = Opts {
            own_device: Some(dev.id),
            push_all: !dev.synced[r],
        };
        let out = match budget {
            None => mirror(&dev.local, &self.remotes[r], &opts),
            Some(b) => mirror(
                &dev.local,
                &Faulty {
                    inner: &self.remotes[r],
                    budget: AtomicUsize::new(b),
                },
                &opts,
            ),
        };
        // As `figlock_sync::run`: a sync with no vault on either side marks nothing.
        if out.is_ok() && dev.local.get("vault.json").is_ok() {
            dev.synced[r] = true;
        }
        out
    }

    fn apply(&mut self, a: &Action) {
        let n = self.devices.len();
        self.unique += 1;
        let u = self.unique;
        match *a {
            Action::Op(d) => {
                let dev = &mut self.devices[d % n];
                dev.ops += 1;
                let path = format!("log/{}/{:08}.op", dev.id, dev.ops);
                dev.local
                    .put_new(&path, format!("op-{u}").as_bytes())
                    .unwrap();
            }
            Action::Bump(d) => {
                let dev = &self.devices[d % n];
                if let Some(rev) = revision(&dev.local) {
                    dev.local
                        .put_replace("vault.json", &vault_json(rev + 1, u))
                        .unwrap();
                    dev.local
                        .put_replace(
                            &format!("devices/{}.json", dev.id),
                            format!("rec-{u}").as_bytes(),
                        )
                        .unwrap();
                }
            }
            // The device syncs to both remotes, the second one flaky. The first must be unaffected.
            Action::Sync(d, budget) => {
                let d = d % n;
                let before = files(&self.devices[d].local);
                let healthy = self.sync_one(d, 0, None);
                assert!(healthy.is_ok(), "a healthy remote syncs: {healthy:?}");
                let flaky = self.sync_one(d, 1, Some(budget));
                if let Err(e) = flaky {
                    assert_eq!(e, SyncError::Offline, "reported as the failure it is");
                }
                // Op files only ever grow on a device, through either remote.
                let after = files(&self.devices[d].local);
                for (path, bytes) in &before {
                    if path.starts_with("log/") {
                        assert_eq!(after.get(path), Some(bytes), "local lost or changed {path}");
                    }
                }
            }
        }
    }

    /// Every device syncs to both remotes, healthy, until a round changes nothing.
    fn settle(&mut self) {
        for round in 0..8 {
            let mut changed = false;
            for d in 0..self.devices.len() {
                for r in 0..2 {
                    let rep = self.sync_one(d, r, None).expect("healthy remotes sync");
                    changed |= rep.pulled + rep.pushed > 0;
                }
            }
            if !changed {
                return;
            }
            assert!(round < 7, "eight rounds did not settle");
        }
    }

    fn assert_converged(&self) {
        let r0 = files(&self.remotes[0]);
        assert_eq!(files(&self.remotes[1]), r0, "the remotes differ");
        for dev in &self.devices {
            assert_eq!(files(&dev.local), r0, "device {} differs", dev.id);
        }
    }
}

#[derive(Clone, Debug)]
enum Action {
    Op(usize),
    Bump(usize),
    Sync(usize, usize),
}

fn action() -> impl Strategy<Value = Action> {
    prop_oneof![
        4 => (0..3usize).prop_map(Action::Op),
        1 => (0..3usize).prop_map(Action::Bump),
        5 => (0..3usize, 0..40usize).prop_map(|(d, b)| Action::Sync(d, b)),
    ]
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(64))]

    /// Devices converge on both remotes however the flaky one fails, and the healthy one is never held back.
    #[test]
    fn two_remotes_converge_with_one_flaky(
        n in 1..=3usize,
        actions in proptest::collection::vec(action(), 0..30),
    ) {
        let mut w = World::new(n);
        for a in &actions {
            w.apply(a);
        }
        w.settle();
        w.assert_converged();
    }
}

fn two_devices() -> World {
    let mut w = World::new(2);
    w.settle();
    w
}

/// A remote that holds another vault is refused, and the other remote still syncs.
#[test]
fn a_remote_with_another_vault_is_refused_and_the_other_remote_still_syncs() {
    let mut w = two_devices();
    let foreign = serde_json::json!({ "vault_id": "other", "revision": 99 }).to_string();
    w.remotes[1]
        .put_replace("vault.json", foreign.as_bytes())
        .unwrap();
    let theirs = files(&w.remotes[1]);
    w.apply(&Action::Op(0));

    assert_eq!(w.sync_one(0, 1, None), Err(SyncError::ForeignVault));
    assert_eq!(
        files(&w.remotes[1]),
        theirs,
        "nothing was written to the foreign remote"
    );
    w.sync_one(0, 0, None).unwrap();
    assert!(w.remotes[0].get("log/aa/00000001.op").is_ok());
}

/// A remote that went back to an older revision (a restored backup) does not drag the device back; it is
/// brought forward instead.
#[test]
fn a_remote_that_goes_backwards_is_ignored() {
    let mut w = two_devices();
    w.apply(&Action::Bump(0));
    w.apply(&Action::Bump(0));
    w.sync_one(0, 0, None).unwrap();
    w.sync_one(0, 1, None).unwrap();
    let top = revision(&w.devices[0].local).unwrap();
    assert!(top >= 3);

    w.remotes[1]
        .put_replace("vault.json", &vault_json(1, 7))
        .unwrap();
    w.sync_one(0, 1, None).unwrap();
    assert_eq!(
        revision(&w.devices[0].local),
        Some(top),
        "the device kept its revision"
    );
    assert_eq!(
        revision(&w.remotes[1]),
        Some(top),
        "and brought the remote forward"
    );
}

/// A remote that was emptied is lost for this device alone: the other remote is not asked to confirm.
#[test]
fn a_lost_remote_needs_confirmation_alone() {
    let mut w = two_devices();
    for e in w.remotes[1].list("").unwrap() {
        w.remotes[1].delete(&e.path).unwrap();
    }
    assert_eq!(w.sync_one(0, 1, None), Err(SyncError::RemoteLost));
    assert!(w.sync_one(0, 0, None).is_ok());
    // The person confirms for that remote only.
    w.devices[0].synced[1] = false;
    w.sync_one(0, 1, None).unwrap();
    w.settle();
    w.assert_converged();
}
